+            <p class="subtitle">Choose any answers that fit each question. Each group allows multiple selections.</p>
+          </header>
+
+          <form id="quiz-form" novalidate>
+            ${quizData.map((item, index) => QuestionCard({ item, index })).join("")}
+
+            <div class="footer-row">
+              <button type="submit">Submit quiz</button>
+              <div class="status" id="quiz-status" aria-live="polite"></div>
+            </div>
