+
+    const form = document.getElementById("quiz-form");
+    const status = document.getElementById("quiz-status");
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const selections = quizData.map((item) => {
+        const values = Array.from(form.querySelectorAll(`input[name="${item.id}"]:checked`)).map((input) => input.value);
+        return `${item.question} ${values.length ? `(${values.join(", ")})` : "(no answers selected)"}`;
+      });
+
+      status.textContent = `Quiz submitted. ${selections.join(" ")}.`;
+      status.dataset.state = "success";
+    });
+  </script>
+</body>
+</html>
