  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a31;
      --panel-2: #18213c;
      --border: #2b355a;
      --text: #eef2ff;
      --muted: #aab3d4;
      --accent: #7c9cff;
      --accent-2: #8ff0c8;
      --focus: #f4c95d;
      --danger: #ff8ca1;
      --shadow: 0 22px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
        linear-gradient(180deg, #08101f 0%, #0b1020 100%);
      color: var(--text);
      line-height: 1.5;
    }

    a.skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-200%);
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: #ffffff;
      color: #111827;
      text-decoration: none;
      font-weight: 700;
      z-index: 10;
    }

    a.skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    main {
      width: min(960px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 3rem 0 4rem;
    }

    .app-shell {
      background: rgba(18, 26, 49, 0.88);
      border: 1px solid rgba(124, 156, 255, 0.18);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(14px);
    }

    .hero {
      padding: 2rem;
      background: linear-gradient(135deg, rgba(124, 156, 255, 0.18), rgba(143, 240, 200, 0.08));
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent-2);
      font-size: 0.88rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.1rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0.85rem 0 0;
      max-width: 62ch;
      color: var(--muted);
    }

    form {
      padding: 1.5rem;
    }

    .form-field {
      margin: 0 0 1.25rem;
    }

    fieldset {
      margin: 0;
      padding: 1.15rem 1.15rem 1.25rem;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: linear-gradient(180deg, rgba(24, 33, 60, 0.92), rgba(18, 26, 49, 0.96));
    }

    legend {
      padding: 0 0.5rem;
      font-size: 1.05rem;
      font-weight: 700;
    }

    .required-marker {
      color: var(--accent-2);
      font-weight: 800;
    }

    .help-text {
      margin: 0.45rem 0 1rem;
      color: var(--muted);
      font-size: 0.96rem;
    }

    .choices {
      display: grid;
      gap: 0.8rem;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      padding: 0.85rem 0.95rem;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 14px;
      background: rgba(255, 255, 255, 0.03);
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(124, 156, 255, 0.45);
      background: rgba(124, 156, 255, 0.08);
    }

    .choice input {
      margin-top: 0.15rem;
      inline-size: 1.1rem;
      block-size: 1.1rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .choice input:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .choice label {
      cursor: pointer;
      color: var(--text);
      font-weight: 600;
    }

    .choice small {
      display: block;
      margin-top: 0.2rem;
      color: var(--muted);
      font-weight: 400;
    }

    .footer-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      justify-content: space-between;
      margin-top: 1.25rem;
      padding: 0 0.15rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.4rem;
      background: linear-gradient(135deg, var(--accent), #5f79ff);
      color: #07111f;
      font: inherit;
      font-weight: 800;
      letter-spacing: 0.01em;
      cursor: pointer;
      box-shadow: 0 10px 30px rgba(124, 156, 255, 0.28);
    }

    button:hover {
      filter: brightness(1.04);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    .status {
      min-height: 1.5rem;
      color: var(--muted);
      font-weight: 600;
    }

    .status[data-state="error"] {
      color: var(--danger);
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 1rem, 960px);
        padding: 2.25rem 0 3rem;
      }

      .hero,
      form {
        padding-left: 1rem;
        padding-right: 1rem;
      }

      fieldset {
        padding: 1rem;
      }
    }

    @media (forced-colors: active) {
      .app-shell,
      fieldset,
      .choice,
      button {
        forced-color-adjust: auto;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content"></main>

  <script>
    const quizData = [
      {
        id: "lang-families",
        question: "Which of these are programming languages?",
        helpText: "Select all that apply.",
        options: [
          { id: "lang-js", label: "JavaScript" },
          { id: "lang-html", label: "HTML" },
          { id: "lang-python", label: "Python" },
          { id: "lang-c", label: "C" }
        ]
      },
      {
        id: "language-paradigms",
        question: "Which languages are commonly used for web development?",
        options: [
          { id: "web-ruby", label: "Ruby" },
          { id: "web-go", label: "Go" },
          { id: "web-css", label: "CSS" },
          { id: "web-typescript", label: "TypeScript" }
        ]
      },
      {
        id: "language-features",
        question: "Which of these are compiled languages?",
        options: [
          { id: "comp-rust", label: "Rust" },
          { id: "comp-sql", label: "SQL" },
          { id: "comp-java", label: "Java" },
          { id: "comp-php", label: "PHP" }
        ]
      }
    ];

    function CheckboxOption({ name, option, description }) {
      const optionId = `${name}-${option.id}`;
      return `
        <div class="choice">
          <input type="checkbox" id="${optionId}" name="${name}" value="${option.label}">
          <label for="${optionId}">
            ${option.label}
            ${description ? `<small>${description}</small>` : ""}
          </label>
        </div>
      `;
    }

    function QuestionCard({ item, index }) {
      const legendId = `${item.id}-legend`;
      const helpId = `${item.id}-help`;
      const options = item.options
        .map((option, optionIndex) =>
          CheckboxOption({
            name: item.id,
            option,
            description: optionIndex === 0 && item.id === "lang-families" ? "Example: language used to build interactive apps." : ""
          })
        )
        .join("");

      return `
        <div class="form-field">
          <fieldset ${item.helpText ? `aria-describedby="${helpId}"` : ""}>
            <legend id="${legendId}">${index + 1}. ${item.question}</legend>
            ${item.helpText ? `<p class="help-text" id="${helpId}">${item.helpText}</p>` : ""}
            <div class="choices">
              ${options}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp() {
      return `
        <section class="app-shell" aria-labelledby="quiz-title">
          <header class="hero">
            <p class="eyebrow">Knowledge check</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="subtitle">Choose any answers that fit each question. Each group allows multiple selections.</p>
          </header>

          <form id="quiz-form" novalidate>
            ${quizData.map((item, index) => QuestionCard({ item, index })).join("")}

            <div class="footer-row">
              <button type="submit">Submit quiz</button>
              <div class="status" id="quiz-status" aria-live="polite"></div>
            </div>
          </form>
        </section>
      `;
    }

    const main = document.getElementById("main-content");
    main.innerHTML = QuizApp();

    const form = document.getElementById("quiz-form");
    const status = document.getElementById("quiz-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selections = quizData.map((item) => {
        const values = Array.from(form.querySelectorAll(`input[name="${item.id}"]:checked`)).map((input) => input.value);
        return `${item.question} ${values.length ? `(${values.join(", ")})` : "(no answers selected)"}`;
      });

      status.textContent = `Quiz submitted. ${selections.join(" ")}.`;
      status.dataset.state = "success";
    });
  </script>
</body>
</html>
